sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // 1. Get Hospital Name dynamically
    var hospitalName = current.x_2223823_apollo_0_hospital ? current.x_2223823_apollo_0_hospital.getDisplayValue() : '';
    gs.addInfoMessage('Hospital Name: ' + hospitalName);

    // Get category and subcategory safely
    var category = current.category ? current.category.toString().toLowerCase().trim() : '';
    gs.addInfoMessage('Category: ' + category);

    var subcategory = current.subcategory ? current.subcategory.toString().toLowerCase().trim() : '';
    gs.addInfoMessage('SubCategory: ' + subcategory);

    var teamKeyword = '';
    var isValidRequest = true; // Safety flag for validation

    // 2. Strict Validation & Logic Matrix
    if (category == 'it') {
        // IT issues don't strictly require subcategory in your rules, but group must exist
        teamKeyword = 'IT Network & Desktop';
    } 
    else if (category == 'facility') {
        // Facility issues map directly to Maintenance
        teamKeyword = 'Maintenance';
    } 
    else if (category == 'other / general services') {
        // STRICT CHECK: If category is 'other', subcategory CANNOT be empty!
        if (!subcategory) {
            isValidRequest = false; 
            gs.addInfoMessage('Validation Failed: Subcategory is missing for Other / General Services.');
        } 
        else if (subcategory.indexOf('housekeeping') > -1) {
            teamKeyword = 'Housekeeping';
        } 
        else if (subcategory.indexOf('security') > -1) {
            teamKeyword = 'Security';
        } 
        else if (subcategory.indexOf('transportation') > -1) {
            teamKeyword = 'Transportation';
        } 
        else {
            // If subcategory doesn't match any known 'other' type -> Force Fallback
            isValidRequest = false;
            gs.addInfoMessage('Validation Failed: Unknown subcategory under Other services.');
        }
    } 
    else {
        // If category itself is unknown or empty -> Force Fallback
        isValidRequest = false;
        gs.addInfoMessage('Validation Failed: Invalid or empty Main Category.');
    }

    // 3. Dynamic Group Query (Only if validation passes and Hospital is selected)
    var assignedSysId = '';

    if (isValidRequest && hospitalName && teamKeyword) {
        var baseHospital = hospitalName.trim(); 

        var grp = new GlideRecord('sys_user_group');
        grp.addQuery('name', 'CONTAINS', baseHospital);
        grp.addQuery('name', 'CONTAINS', teamKeyword);
        grp.query();

        if (grp.next()) {
            assignedSysId = grp.getUniqueValue();
            gs.addInfoMessage('Dynamically Matched Group: ' + grp.getValue('name'));
        } else {
            gs.addInfoMessage('Warning: Hospital group found for keyword "' + teamKeyword + '", but name mismatch in DB.');
        }
    }

    // 4. Assign Group or Fallback Queue
    if (assignedSysId) {
        current.assignment_group = assignedSysId;
    } else {
        gs.addInfoMessage('Routing to Fallback Queue due to missing match, invalid category, or blank subcategory.');
        var fallbackGrp = new GlideRecord('sys_user_group');
        if (fallbackGrp.get('name', 'Apollo Support - Fallback Queue')) {
            current.assignment_group = fallbackGrp.getUniqueValue();
        }
    }

})(current, previous);
